/// Vector asset generator for WeChat Pay payment branding.
class WeChatPayAssets {
  WeChatPayAssets._();

  /// Renders the official full WeChat Pay logo (emblem + "WeChat Pay" wordmark).
  static Widget logo({required WeChatPayColor color, double height = 24.0}) {
    final String svg = switch (color) {
      WeChatPayColor.green => _weChatPayLogoWhiteSvg,
      WeChatPayColor.white => _weChatPayLogoDarkSvg,
      WeChatPayColor.black => _weChatPayLogoBlackBgSvg,
    };

    return SvgPicture.string(
      svg,
      height: height,
      fit: BoxFit.contain,
    );
  }

  /// Renders the standalone iconic WeChat chatting bubbles emblem.
  static Widget emblem({required WeChatPayColor color, double height = 24.0}) {
    final String svg = color == WeChatPayColor.green
        ? _weChatPayEmblemWhiteSvg
        : _weChatPayEmblemGreenSvg;

    return SvgPicture.string(
      svg,
      height: height,
      fit: BoxFit.contain,
    );
  }

